const DiscoveryIntake=(()=>{
 let executiveAccess=false,membershipToken='';
 const storageKey='couture-discovery-v3';let profile={},stage=0;
 try{profile=JSON.parse((globalThis.CoutureAccount?.storage || localStorage).getItem(storageKey)||'{}')||{};}catch{}
 const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const roles=['Individual Professional / Emerging Leader','Manager / Director','Vice President / Senior Vice President','C-Suite Executive / CEO / President','CHRO / CPO / HR Executive','Talent Management / Learning & Development Leader','Business Owner / Founder','Academic Leader / Faculty','Other'];
 const reasons=['Individual Leadership Development & Career Advancement','Executive Coaching & Leadership Effectiveness','Executive Team Effectiveness & Strategic Alignment','Leadership Team Performance & Organizational Alignment','Executive Succession & High-Potential Leadership Development','Organizational Transformation & Strategic Change Leadership','Enterprise Leadership Strategy & Capability Development','Organizational Culture & Leadership Effectiveness','Academic Leadership Development & Executive Education Partnerships','Exploring Couture Leadership™ Offerings'];
 const industries=['Agriculture','Arts & Entertainment','Construction','Education','Energy & Utilities','Financial Services','Government & Public Administration','Healthcare','Hospitality & Tourism','Legal & Professional Services','Manufacturing','Nonprofit','Real Estate','Retail & Consumer Goods','Technology','Transportation & Logistics','Currently exploring a career transition','Other'];
 const priorities=['Purpose and direction','Strategic thinking','Decision-making','Communication','Executive presence','Influence','Emotional intelligence','Inclusive leadership','Team effectiveness','Change leadership','Career advancement','Accountability and execution','Sustainable leadership habits'];
 const assessments=['DiSC','HBDI®','MBTI®','CliftonStrengths','Hogan Assessments','Insights'];
 const states='Alabama|Alaska|Arizona|Arkansas|California|Colorado|Connecticut|Delaware|District of Columbia|Florida|Georgia|Hawaii|Idaho|Illinois|Indiana|Iowa|Kansas|Kentucky|Louisiana|Maine|Maryland|Massachusetts|Michigan|Minnesota|Mississippi|Missouri|Montana|Nebraska|Nevada|New Hampshire|New Jersey|New Mexico|New York|North Carolina|North Dakota|Ohio|Oklahoma|Oregon|Pennsylvania|Rhode Island|South Carolina|South Dakota|Tennessee|Texas|Utah|Vermont|Virginia|Washington|West Virginia|Wisconsin|Wyoming'.split('|');
 const countries=['United States','Canada','United Kingdom','Australia','India','South Africa','Other'];
 const tiers=['Free | Discover Your Leadership','Individual | My Leadership Journey','CHRO/CPO | Executive Development Partnership','Enterprise | Collective Leadership Effectiveness','Academia | Leadership Development & Career Readiness'];
 const list=(name)=>Array.isArray(profile[name])?profile[name]:[];
 function input(name,label,type='text',required=true,placeholder=''){return `<label>${label}<input placeholder="${esc(placeholder)}" name="${name}" type="${type}" value="${esc(profile[name])}" maxlength="1500" ${required?'required':''}></label>`;}
 function select(name,label,options,required=true,prompt='Select'){return `<label>${label}<select name="${name}" ${required?'required':''}><option value="">${esc(prompt)}</option>${options.map(o=>`<option ${profile[name]===o?'selected':''}>${esc(o)}</option>`).join('')}</select></label>`;}
 function checks(name,label,options,radio=false){return `<fieldset><legend>${label}</legend>${name==='reasons'?'<p class="discovery-helper">Select all that apply.</p>':''}${options.map(o=>`<label><input type="${radio?'radio':'checkbox'}" name="${name}" value="${esc(o)}" ${(radio?profile[name]===o:list(name).includes(o))?'checked':''} ${radio?'required':''}>${esc(o)}</label>`).join('')}</fieldset>`;}
 function save(){try{(globalThis.CoutureAccount?.storage || localStorage).setItem(storageKey,JSON.stringify(profile));}catch{}}
 function capture(form){const data=new FormData(form);for(const [k,v] of data)profile[k]=v;for(const name of ['reasons','priorities','assessments'])if(form.querySelector(`[name="${name}"]`))profile[name]=data.getAll(name);save();}
 function banner(part=0){return `<header class="discovery-banner"><p class="discovery-eyebrow">COUTURE LEADERSHIP™ | ${part===0?'WELCOME & DISCOVERY':'DISCOVER YOUR LEADERSHIP'}</p><h2>${part===0?'Your leadership journey begins here.':part===1?(profile.firstName?esc(profile.firstName)+', let’s tailor your experience.':'Let’s tailor your experience.'):part===2?'Part II — How You Think & Communicate':'Part III — Discover Your Leadership'}</h2>${part===1?'<p>Part I — Understanding You</p>':''}<p>${part===3?'Reflect on your leadership to discover your strengths and opportunities for growth.':'Tell us a little about yourself and what brings you to Couture Leadership™ so we can tailor your experience.'}</p></header>`;}
 function render(){const host=document.getElementById('assessment');host.innerHTML=`<div class="report-panel v3-section discovery-card">${banner(stage)}<p>Your details stay in this browser. You may clear them below.</p><form class="v3-form" id="discovery-form">${stage===0?input('firstName','First name','text',true,'First name')+input('lastName','Last name','text',true,'Last name')+'<div class=full>'+input('email','Email address','email',true,'you@example.com')+'</div><div class=full>'+select('role','Which best describes your current role?',roles,true,'Select your role')+'</div>'+checks('reasons','What brings you to Couture Leadership™?',reasons)+`<div class="full" id="immediate-wrap">${input('immediate','Most Immediate Priority','text',false)}</div>`:stage===1?select('industry','1. Industry',industries)+select('country','2. Country',countries)+`<div id="region-wrap">${region()}</div>`+input('title','3. Current/Most Recent Title')+select('experience','4. Years of Experience',['Less than 1 year','1–5 years','6–10 years','11–15 years','16–20 years','21+ years'])+select('size','5. Organization Size',['Independent / Solo','2–10','11–50','51–200','201–500','501–1,000','1,001–5,000','5,001+'])+input('goal','6. 12–24 Month Professional Goal')+checks('priorities','7. Immediate Development Priority (select up to 2)',priorities):checks('assessments','8. Previous assessments (optional)',[...assessments,'Skip / N/A'])+`<div class="full" id="share-wrap">${select('share','9. Would you like to share optional findings?',['Yes','Not at this time'],false)}</div><div class="full" id="assessment-details"></div>`+input('thinking','10. What have you learned about how you prefer to think, communicate, or work with others?','text',false)+'<p>Privacy: Prior assessment data is supplementary context only and never alters pillar scores. Sharing is optional. Omit sensitive assessment information.</p>'}<p id="intake-error" role="alert"></p><div class="full"><button class="secondary" type="button" id="intake-back">← ${stage?'Previous part':'Overview'}</button> <button class="primary" type="submit">${stage===2?'Begin Part III — Discover Your Leadership':'Continue →'}</button></div></form><button class="reset" id="clear-discovery">Clear personal intake data</button></div>`;
 const form=host.querySelector('form');function update(){if(stage===0){const n=form.querySelectorAll('[name=reasons]:checked').length;document.getElementById('immediate-wrap').hidden=n<2;form.elements.immediate.required=n>1;}if(stage===2){const selected=[...form.querySelectorAll('[name=assessments]:checked')].map(e=>e.value).filter(v=>v!=='Skip / N/A');document.getElementById('share-wrap').hidden=!selected.length;document.getElementById('assessment-details').innerHTML=selected.length&&form.elements.share.value==='Yes'?selected.map(a=>`<fieldset><legend>${esc(a)}</legend>${input(a+'Name','Assessment Name','text',false)}${input(a+'Findings','Primary Findings','text',false)}${select(a+'Timeframe','Completion Timeframe',['Within the past year','1–3 years ago','More than 3 years ago','Unsure'],false)}${select(a+'Accuracy','Perceived Accuracy',['Very accurate','Somewhat accurate','Not accurate','Unsure'],false)}</fieldset>`).join(''):'';}}
 update();form.addEventListener('change',e=>{if(e.target.name==='assessments'){if(e.target.value==='Skip / N/A'&&e.target.checked)form.querySelectorAll('[name=assessments]').forEach(el=>{if(el!==e.target)el.checked=false;});else if(e.target.checked)form.querySelector('[value="Skip / N/A"]').checked=false;}capture(form);if(e.target.name==='country'){profile.region='';document.getElementById('region-wrap').innerHTML=region();}if(['share','assessments','reasons'].includes(e.target.name))update();});
 form.addEventListener('submit',e=>{e.preventDefault();capture(form);const error=document.getElementById('intake-error');if(stage===0&&!list('reasons').length){error.textContent='Please select at least one reason.';return;}if(stage===1&&(!list('priorities').length||list('priorities').length>2)){error.textContent='Please select one or two development priorities.';return;}if(stage<2){stage++;render();}else{profile.complete=true;save();renderAssessment();}window.scrollTo(0,0);});
 document.getElementById('intake-back').onclick=()=>{capture(form);if(stage){stage--;render();}else navigate('dashboard');};document.getElementById('clear-discovery').onclick=()=>{profile={};save();stage=0;render();};
 }
 function region(){return profile.country==='United States'?select('region','State / District',states):profile.country==='Canada'?select('region','Province / Territory',['Alberta','British Columbia','Manitoba','New Brunswick','Newfoundland and Labrador','Nova Scotia','Ontario','Prince Edward Island','Quebec','Saskatchewan','Northwest Territories','Nunavut','Yukon']):input('region','State / Province (if applicable)','text',false);}
 function pathway(){if(/Academic/.test(profile.role)||list('reasons').some(r=>/academic/i.test(r)))return tiers[4];if(/CHRO|Talent Management/.test(profile.role))return tiers[2];if(/C-Suite|Business Owner/.test(profile.role)||list('reasons').includes(reasons[6]))return tiers[3];return tiers[1];}
 function enrich(){const host=document.getElementById('results');if(document.getElementById('discovery-extras'))return;const ranked=dimensions.map((d,i)=>({name:d.name,value:score(values(i)),action:d.action})).sort((a,b)=>b.value-a.value);const extra=document.createElement('div');extra.id='discovery-extras';extra.className='report-panel v3-section';extra.innerHTML=`<h2>Part IV — Leadership Intelligence Snapshot</h2><p>${esc(profile.firstName)}, your five-pillar visual profile above uses only your 15 equally weighted frequency responses.</p><h3>Preliminary strengths</h3><p>${ranked.slice(0,2).map(d=>d.name).join(' · ')} (highest self-reported scores; ties may occur).</p><h3>Development opportunities</h3><p>${ranked.slice(-2).map(d=>d.name).join(' · ')} (relative priorities for exploration).</p><h3>Aspirations alignment</h3><p>Your stated goal: ${esc(profile.goal)}. Consider how practicing ${ranked.at(-1).name.toLowerCase()} could support that aspiration; reflect on what evidence of progress would look like.</p><h3>Participant-reported thinking / communication summary</h3><p>${esc(profile.thinking||'No thinking preferences shared.')} ${esc(profile.share==='Yes'?list('assessments').filter(a=>a!=='Skip / N/A').map(a=>a+': '+(profile[a+'Findings']||'No findings shared')).join(' · '):'Prior assessment findings were not shared.')}</p><p>These self-reported preferences are supplementary context only and never alter scores.</p><h3>One practical initial development recommendation</h3><p>${ranked.at(-1).action}</p><section aria-labelledby="decision-check-title"><h3 id="decision-check-title">Leadership Decision Check (Quick Use)</h3><ol><li><strong>Purpose:</strong> What should I prioritize, delay, or stop to create meaningful impact?</li><li><strong>Precision:</strong> Have I paused, expanded perspectives, validated evidence, analyzed, and diagnosed before I act?</li><li><strong>Presence:</strong> Am I accessible, keeping my 1:1s, giving specific feedback, and communicating clear expectations?</li><li><strong>Tailoring:</strong> Have I considered the individual, context, motivation, communication, and consistency, and asked how this person prefers to be managed and supported?</li><li><strong>Craftsmanship:</strong> What do my journal of team wins and growth areas and structured reflection tell me to retain, refine, or retire?</li></ol></section><h2>Part V — Pathway Recommendations</h2><div class="v3-grid"><article><h3>${tiers[0]}</h3><p>Your complimentary discovery experience.</p></article><article><h3>${esc(pathway())}</h3><p>Suggested from your role and interests, subject to membership eligibility.</p><a href="/#memberships">Explore membership →</a></article></div><h2>Part VI — Discovery Milestone</h2><article id="discovery-certificate"><h3>Couture Leadership™ Discovery Milestone</h3><p>Presented to ${esc(profile.firstName)} ${esc(profile.lastName)}</p><p>Participation milestone · Completed the complimentary discovery experience.</p><p>Not a credential or certification. No competency, mastery, or credential is conferred.</p><p>${new Date().toLocaleDateString()}</p></article><button class="secondary" data-print="#discovery-certificate">Print / Save milestone as PDF</button> <button class="primary" id="download-milestone">Download participation milestone</button><p>Credentials are earned through documented achievement and never purchased.</p>`;host.append(extra);document.getElementById('download-milestone').onclick=()=>{const blob=new Blob(['<!doctype html><html lang="en"><meta charset="utf-8"><title>Discovery Milestone</title><body>'+document.getElementById('discovery-certificate').outerHTML+'</body></html>'],{type:'text/html'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='couture-discovery-participation-milestone.html';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};}
 function decorate(view){if(globalThis.CoutureAccount?.paid){document.querySelectorAll('.v3-gate').forEach(el=>el.remove());return;}if(profile.firstName)document.getElementById('page-title').textContent=profile.firstName+', '+document.getElementById('page-title').textContent.replace(/^./,s=>s.toLowerCase());document.querySelectorAll('.v3-gate').forEach(el=>el.remove());if(['simulator','career','enterprise'].includes(view)){const notice=document.createElement('div');notice.className='v3-notice v3-gate';notice.innerHTML='<b>Paid membership module · Preview / demo mode</b><p>Explore sample tools. Ongoing Couture Leadership™ Coach sessions, Decision Simulator, Career Architect, and CHRO/Enterprise Analytics require eligible paid membership. Sample analytics are illustrative.</p><a href="/#memberships">Explore eligible memberships →</a>';const access=document.createElement('details');access.innerHTML='<summary>Executive Preview / Member Access</summary><p>Local preview supports live coaching when configured by the server. Public access requires eligible paid membership.</p><label><input type="checkbox" id="executive-access"> Enable Executive Preview / Member Access</label><label for="coach-member-token">Member access token (optional for local preview)</label><input id="coach-member-token" type="password" autocomplete="off" aria-describedby="coach-access-note"><p id="coach-access-note" role="status"></p>';notice.append(access);const toggle=access.querySelector('#executive-access'),token=access.querySelector('#coach-member-token'),status=access.querySelector('#coach-access-note');toggle.checked=executiveAccess;token.value=membershipToken;function updateAccess(){executiveAccess=toggle.checked;membershipToken=token.value.trim();token.disabled=!executiveAccess;status.textContent=executiveAccess?'Executive access selected. Server authorization still applies. Tokens stay in memory for this page session.':'Demo mode selected. Enable executive access to supply a member token; local preview requests remain available.';}toggle.onchange=updateAccess;token.oninput=updateAccess;updateAccess();document.getElementById(view).before(notice);}}
 return {render,banner,enrich,decorate,coachHeaders:()=>executiveAccess&&membershipToken?{Authorization:`Bearer ${membershipToken}`}:{},ready:()=>profile.complete===true,context:()=>({firstName:profile.firstName||'',careerStage:profile.role||'',aspirations:profile.goal||'',thinkingPreferences:profile.thinking||''})};
})();
